#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

long long gcdOf(long long a, long long b) {
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> rect(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> rect[i][j];
        }
    }

    unordered_map<long long, long long> count;
    long long total = 0;
    for (int i = 0; i < n; i++) {
        long long g = gcdOf(rect[i][0], rect[i][1]);
        long long key = (rect[i][0] / g) * 1000000007LL + rect[i][1] / g;
        total += count[key];
        count[key]++;
    }
    cout << total << "\n";

    return 0;
}

