import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long gcdOf(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] rect = new long[(int) n][2];
        for (int i = 0; i < rect.length; i++) {
            for (int j = 0; j < rect[i].length; j++) {
                rect[i][j] = Long.parseLong(next());
            }
        }

        Map<Long, Long> count = new HashMap<>();
        long total = 0;
        for (int i = 0; i < n; i++) {
            long g = gcdOf(rect[i][0], rect[i][1]);
            long key = (rect[i][0] / g) * 1000000007L + rect[i][1] / g;
            total += count.getOrDefault(key, 0L);
            count.merge(key, 1L, Long::sum);
        }
        System.out.println(total);
    }
}
